t = int(input())
for _ in range(t):
	(n, m) = map(int, input().split())
	grid = []
	ans1 = 0
	ans2 = 0
	for i in range(n):
		grid.append(input())
	if not (n % 2 == 1 and m % 2 == 1):
		for i in range(n):
			for j in range(m):
				if (i + j) % 2 == 0:
					cmp = '*'
				else:
					cmp = '.'
				if grid[i][j] != cmp:
					ans1 += 1
				else:
					ans2 += 1
		print(min(ans1, ans2))
	else:
		for i in range(n):
			for j in range(m):
				if (i + j) % 2 == 0:
					cmp = '*'
				else:
					cmp = '.'
				if grid[i][j] != cmp:
					ans1 += 1
		print(ans1)
